bool Pm3Wsn::creatingDataPacket(Node x, int des, PktId pkt, Data data) {
    if (!((ND.count(x) > 0 && Dests.count(x) == 0)))
        return false;
    if (!(x == initialSrcAddr.at(pkt)))
        return false;
    if (!((finalDestAddr.count(pkt) > 0 && des == finalDestAddr.at(pkt))))
        return false;
    if (!(pktFwdr.count(pkt) == 0))
        return false;
    if (!(pktData.count(pkt) == 0))
        return false;
    if (!(ndBuff.count({x, pkt}) == 0))
        return false;
    if (!(type.at(pkt) == DATA))
        return false;
    if (!(!senseBuff.empty()))
        return false;
    if (!((senseBuff.count(x) > 0 && senseBuff.at(x).count(data) > 0)))
        return false;
    createdPkts.insert(pkt);
    pktFwdr[pkt] = x;
    pktData[pkt] = data;
    ndBuff.insert({x, pkt});
    senseBuff[x].erase(data); if (senseBuff[x].empty()) senseBuff.erase(x);
    return true;
}

bool Pm3Wsn::start_tx(Node x, PktId pkt) {
    if (!(sentDown.count({x, pkt}) == 0))
        return false;
    if (!(sentUp.count({x, pkt}) == 0))
        return false;
    if (!(pktFwdr.count(pkt) > 0))
        return false;
    if (!(ndBuff.count({x, pkt}) > 0))
        return false;
    sentDown.insert({x, pkt});
    pktFwdr[pkt] = x;
    ndBuff.erase({x, pkt});
    return true;
}

// Event-B: send_down — emitted under its SensorApp name (thesis S4, transmit).
bool Pm3Wsn::sendSensorPacket(Node x, PktId pkt) {
    if (!(sentDown.count({x, pkt}) > 0))
        return false;
    // — SensorApp transmit structure (SensorApp::sendSensorPacket) —
    if (socket == nullptr || sinkAddress.isUnspecified()) {
        EV_WARN << "socket/sinkAddress not ready, skipping send\n";
        return false;
    }
    char pktName[32];
    snprintf(pktName, sizeof(pktName), "sensor-%ld", sendSeqNo);
    Packet *packet = new Packet(pktName);
    auto payload = makeShared<ByteCountChunk>(B(payloadLength));
    packet->insertAtBack(payload);
    packet->addTag<PacketProtocolTag>()->setProtocol(&Protocol::manet);
    packet->addTag<L3AddressReq>()->setDestAddress(sinkAddress);
    emit(packetSentSignal, packet);
    socket->send(packet);
    sendSeqNo++;
    sentCount++;
    return true;
}

// Event-B: send_up — emitted under its SensorApp name (thesis S5, receive).
bool Pm3Wsn::socketDataArrived(Node x, PktId pkt, const std::set<Node>& nbrs) {
    if (!(sentUp.count({x, pkt}) == 0))
        return false;
    if (!(sentDown.count({x, pkt}) > 0))
        return false;
    if (!(ctlNeighbours.count(pkt) == 0))
        return false;
    if (!(!nbrs.empty()))
        return false;
    // — SensorApp receive structure (accounting; the packet object itself
    //   is handled in socketDataArrived, which calls this event) —
    receivedCount++;
    for (auto _v : nbrs) ctlNeighbours[pkt].insert(_v);
    sentDown.erase({x, pkt});
    sentUp.insert({x, pkt});
    return true;
}

bool Pm3Wsn::receive(Node nb, PktId pkt) {
    if (!(recvBuff.count({nb, pkt}) == 0))
        return false;
    if (!(sentUp.count({nb, pkt}) == 0))
        return false;
    if (!(sentDown.count({nb, pkt}) == 0))
        return false;
    recvBuff.insert({nb, pkt});
    ctlNeighbours[pkt].erase(nb); if (ctlNeighbours[pkt].empty()) ctlNeighbours.erase(pkt);
    return true;
}

bool Pm3Wsn::clear_recvdBuff(Node nb, PktId pkt) {
    if (!(recvBuff.count({nb, pkt}) > 0))
        return false;
    if (!(clrRecvBuffFlg.count({nb, pkt}) > 0))
        return false;
    recvBuff.erase({nb, pkt});
    return true;
}

bool Pm3Wsn::fwdr_receive_pkt(Node nb, PktId pkt) {
    if (!(recvBuff.count({nb, pkt}) > 0))
        return false;
    if (!(clrRecvBuffFlg.count({nb, pkt}) == 0))
        return false;
    if (!(Dests.count(nb) == 0))
        return false;
    if (!(ndBuff.count({nb, pkt}) == 0))
        return false;
    clrRecvBuffFlg.insert({nb, pkt});
    ndBuff.insert({nb, pkt});
    return true;
}

bool Pm3Wsn::dest_recv_pkt(Node nb, PktId pkt) {
    if (!(recvBuff.count({nb, pkt}) > 0))
        return false;
    if (!(clrRecvBuffFlg.count({nb, pkt}) == 0))
        return false;
    if (!(destBuff.count({nb, pkt}) == 0))
        return false;
    destBuff.insert({nb, pkt});
    clrRecvBuffFlg.insert({nb, pkt});
    return true;
}

bool Pm3Wsn::finish_tx_pkt(Node x, PktId pkt) {
    if (!((ctlNeighbours.count(pkt) == 0 || ctlNeighbours.at(pkt).empty())))
        return false;
    if (!(inRan(sentUp, pkt)))
        return false;
    if (!(!inRan(sentDown, pkt)))
        return false;
    if (!(inDom(sentUp, x)))
        return false;
    if (!(sentUp.count({x, pkt}) > 0))
        return false;
    if (!(inRan(ndBuff, pkt)))
        return false;
    sentUp.erase({x, pkt});
    return true;
}

bool Pm3Wsn::final_tx_pkt(PktId pkt) {
    if (!((ctlNeighbours.count(pkt) == 0 || ctlNeighbours.at(pkt).empty())))
        return false;
    if (!(inRan(sentUp, pkt)))
        return false;
    if (!(!inRan(sentDown, pkt)))
        return false;
    if (!(!inRan(ndBuff, pkt)))
        return false;
    for (auto it = sentUp.begin(); it != sentUp.end(); ) it->second == pkt ? it = sentUp.erase(it) : ++it;
    return true;
}

bool Pm3Wsn::creatingControlPacket(Node x, int des, PktId pkt, Data data) {
    if (!((ND.count(x) > 0 && Dests.count(x) == 0)))
        return false;
    if (!(x == initialSrcAddr.at(pkt)))
        return false;
    if (!((finalDestAddr.count(pkt) > 0 && des == finalDestAddr.at(pkt))))
        return false;
    if (!(pktFwdr.count(pkt) == 0))
        return false;
    if (!(pktData.count(pkt) == 0))
        return false;
    if (!(ndBuff.count({x, pkt}) == 0))
        return false;
    if (!(data == CTL_VAL))
        return false;
    if (!(CONTROL.count(type.at(pkt)) > 0))
        return false;
    createdPkts.insert(pkt);
    pktFwdr[pkt] = x;
    pktData[pkt] = data;
    ndBuff.insert({x, pkt});
    return true;
}

